package greenhouse;
import greenhouse.a.*;import greenhouse.b.*;import greenhouse.c.*;import greenhouse.facade.*;import greenhouse.workflow.*;
import org.junit.jupiter.api.*;import java.nio.file.*;import java.io.*;import static org.junit.jupiter.api.Assertions.*;
public class GreenhouseTest {
 Path dir;ScheduleService a;VentilationService b;NutrientService c;JobRepository jobs;GreenhouseFacade facade;AdminFacade admin;
 @BeforeEach void setup() throws IOException {dir=Files.createTempDirectory("greenhouse-test");a=new ScheduleService(new SoilRule(),new ScheduleRepository(dir));b=new VentilationService(new ClimateRule(),new VentilationRepository(dir));c=new NutrientService(new NutrientRule(),new NutrientsRepository(dir));jobs=new JobRepository(dir);facade=new GreenhouseFacade(a,b,c,jobs);admin=new AdminFacade(a,b,c,jobs);}
 private void assertWorkflowIs(String id,Job.Stage stage){assertEquals(stage,new JobRepository(dir).find(id).stage);}
 @Test void success(){facade.start("ok",20,25,2);assertWorkflowIs("ok",Job.Stage.COMPLETED);assertEquals(Schedule.Status.RESERVED,a.find("ok").status());assertEquals(Ventilation.Status.ACTIVE,b.find("ok").status());assertEquals(Nutrients.Status.DISPENSED,c.find("ok").status());}
 @Test void bFailureUndoesOnlyA(){facade.start("bFail",20,50,2);assertWorkflowIs("bFail",Job.Stage.COMPENSATED);assertEquals(Schedule.Status.CANCELLED,new ScheduleRepository(dir).find("bFail").status());assertNull(b.find("bFail"));}
 @Test void cFailureUndoesBThenA(){facade.start("cFail",20,25,0);assertWorkflowIs("cFail",Job.Stage.COMPENSATED);assertEquals(Ventilation.Status.STOPPED,new VentilationRepository(dir).find("cFail").status());assertEquals(Schedule.Status.CANCELLED,new ScheduleRepository(dir).find("cFail").status());}
 @Test void reloadMidChain(){facade.pauseAfterA("restart",20,25,2);assertWorkflowIs("restart",Job.Stage.PENDING_B);var newFacade=new GreenhouseFacade(new ScheduleService(new SoilRule(),new ScheduleRepository(dir)),new VentilationService(new ClimateRule(),new VentilationRepository(dir)),new NutrientService(new NutrientRule(),new NutrientsRepository(dir)),new JobRepository(dir));newFacade.resume("restart");assertWorkflowIs("restart",Job.Stage.COMPLETED);}
 @Test void reloadPendingC(){facade.pauseAfterA("pendingC",20,25,2);b.execute("pendingC",25);Job j=jobs.find("pendingC");j.stage=Job.Stage.PENDING_C;jobs.save(j);facade.resume("pendingC");assertWorkflowIs("pendingC",Job.Stage.COMPLETED);}
 @Test void manualCompensation(){facade.pauseAfterA("manual",20,25,2);admin.compensate("manual");admin.compensate("manual");assertWorkflowIs("manual",Job.Stage.COMPENSATED);}
 @Test void invalidInputAndDuplicate(){assertThrows(IllegalArgumentException.class,()->facade.start("invalid",99,25,2));facade.start("same",20,25,2);assertThrows(IllegalArgumentException.class,()->facade.start("same",20,25,2));assertThrows(IllegalArgumentException.class,()->facade.start("../escape",20,25,2));}
 @Test void inspectAndFinalized(){assertEquals("Unknown ID",admin.inspect("missing"));facade.start("done",20,25,2);assertTrue(admin.inspect("done").contains("COMPLETED"));assertThrows(IllegalStateException.class,()->admin.compensate("done"));}
 @Test void entitiesProtectTransitions(){Schedule s=new Schedule("x");assertThrows(IllegalStateException.class,s::cancel);s.reserve();assertThrows(IllegalStateException.class,s::reserve);s.cancel();Ventilation v=new Ventilation("x");assertThrows(IllegalStateException.class,v::stop);v.activate();v.stop();Nutrients n=new Nutrients("x");assertThrows(IllegalStateException.class,n::cancel);n.dispense();n.cancel();}
 @Test void rulesAndServicesDirectly(){assertFalse(new SoilRule().allowed(60));assertFalse(new SoilRule().allowed(-1));assertFalse(new ClimateRule().allowed(9));assertFalse(new ClimateRule().allowed(41));assertFalse(new NutrientRule().allowed(0));a.execute("directA",20);b.execute("directB",25);c.execute("directC",1);assertNotNull(a.find("directA"));assertNotNull(b.find("directB"));assertNotNull(c.find("directC"));a.undo("directA");b.undo("directB");c.undo("directC");}
 @Test void resumeAndMissing(){assertThrows(IllegalArgumentException.class,()->facade.resume("missing"));assertThrows(IllegalArgumentException.class,()->admin.compensate("missing"));facade.start("finished",20,25,1);assertWorkflowIs("finished",facade.resume("finished").stage);}
}
